$Prepared = @()
try {
  foreach ($Plan in $Plans) {
    $Path = Join-Path $Project $Plan.Rel
    if (-not (Test-Path -LiteralPath $Path)) { throw ('Missing file: ' + $Path) }
    $Actual = Get-Sha256 $Path
    if ($Actual -ne $Plan.OldSha) { throw ($Plan.Rel + ': source SHA mismatch. Expected ' + $Plan.OldSha + ', got ' + $Actual) }
    $BackupFile = Join-Path $Backup ([IO.Path]::GetFileName($Path))
    Copy-Item -LiteralPath $Path -Destination $BackupFile -Force
    $Text = [IO.File]::ReadAllText($Path, $Utf8NoBom)
    $Number = 0
    foreach ($Patch in $Plan.Patches) {
      $Number++
      $Text = Replace-Exactly $Text $Patch.Old $Patch.New ($Plan.Rel + ' patch ' + $Number)
    }
    if ($Text.Contains([char]0xFFFD)) { throw ($Plan.Rel + ': U+FFFD detected') }
    $Temp = $Path + '.package7.tmp'
    [IO.File]::WriteAllText($Temp, $Text, $Utf8NoBom)
    $TempSha = Get-Sha256 $Temp
    if ($TempSha -ne $Plan.NewSha) { throw ($Plan.Rel + ': target SHA mismatch. Expected ' + $Plan.NewSha + ', got ' + $TempSha) }
    $Prepared += [pscustomobject]@{ Path = $Path; Temp = $Temp; Backup = $BackupFile }
  }
  foreach ($Item in $Prepared) { Move-Item -LiteralPath $Item.Temp -Destination $Item.Path -Force }
} catch {
  foreach ($Item in $Prepared) {
    if (Test-Path -LiteralPath $Item.Temp) { Remove-Item -LiteralPath $Item.Temp -Force -ErrorAction SilentlyContinue }
    if (Test-Path -LiteralPath $Item.Backup) { Copy-Item -LiteralPath $Item.Backup -Destination $Item.Path -Force -ErrorAction SilentlyContinue }
  }
  throw
}
Write-Host ('Backup: ' + $Backup)
foreach ($Plan in $Plans) { Write-Host ($Plan.Rel + ' SHA256=' + (Get-Sha256 (Join-Path $Project $Plan.Rel))) }
Write-Host 'PACKAGE7_PHOTO_SAFETY_APPLIED_OK'
Write-Host 'Next: flutter analyze'
